window.CA = {"date": "Tuesday, 14 July 2026", "updated": "2026-07-14 14:27", "updated_label": "14 Jul 2026, 14:27 IST", "items": [{"title": "Iran Strikes UAE Oil Tankers in Strait of Hormuz; One Indian Sailor Killed, Several Injured", "category": "ir", "category_name": "International Relations", "summary": "Iranian missiles struck UAE-flagged oil tankers in the Strait of Hormuz, killing one Indian sailor and injuring six to eight others. India's Ministry of External Affairs summoned Iran's senior-most diplomat in New Delhi to protest the attack on Indian nationals aboard commercial vessels. The incident occurred amid an active US-Iran military conflict, with the US having launched multiple rounds of strikes on Iran. The attack on commercial shipping in a critical global waterway has sharply escalated geopolitical and economic tensions.", "exam_angle": "Tests knowledge of India's diplomatic protocol (summoning envoys), India's responsibility to protect its diaspora/sailors abroad, and the strategic importance of the Strait of Hormuz for India's energy security and trade.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["1 Indian sailor killed, 6–8 injured in Iranian missile strikes on UAE tankers in Hormuz", "MEA summoned Iran's senior-most diplomat; action taken by Ministry of External Affairs", "Strait of Hormuz: ~20% of global oil trade passes through it; Iran and Oman share jurisdiction", "Incident date: July 14, 2026"], "source": "The Hindu / NDTV", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "US Announces 20% Toll on Ships Using Strait of Hormuz; Trump Claims Control of Waterway", "category": "ir", "category_name": "International Relations", "summary": "US President Donald Trump announced a 20% fee (toll) on all cargo ships transiting the Strait of Hormuz, alongside a proposed blockade of Iran. Trump claimed the US would function as 'guardian' of the strait and should be reimbursed by nations benefiting from its security. Iran rejected the demand, calling it excessive. The move has significant implications for global oil trade, India's energy imports, and international maritime law under UNCLOS.", "exam_angle": "Relevant to international maritime law (UNCLOS — right of innocent passage through international straits), India's energy security (over 60% of India's crude oil imports transit Hormuz), and US-Iran geopolitics.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Trump proposed 20% toll on all cargo transiting Strait of Hormuz", "Strait of Hormuz: bordered by Iran and Oman; ~21 million barrels of oil/day pass through it", "UNCLOS guarantees 'transit passage' rights through international straits", "India imports ~60–65% of its crude oil from the Gulf; heavily exposed to Hormuz disruptions"], "source": "NDTV / The Hindu", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "UAE Plans New Port on East Coast to Bypass Strait of Hormuz", "category": "places", "category_name": "Places in News", "summary": "The UAE announced plans to build a new port on its east coast (facing the Gulf of Oman) to reduce dependence on the Strait of Hormuz amid escalating US-Iran conflict. The port would allow UAE oil exports to bypass the strait entirely. State oil company ADNOC also tweaked offshore oil pricing to support non-Hormuz supply routes. This is a significant strategic infrastructure response to the crisis.", "exam_angle": "Relevant to understanding alternative maritime routes, energy security strategy, and the geopolitical significance of the Strait of Hormuz for Gulf nations and global trade.", "gs_paper": "GS Paper 1 (Geography)", "key_facts": ["UAE planning new east coast port to bypass Strait of Hormuz", "Port would face the Gulf of Oman, allowing direct access to Indian Ocean", "UAE's ADNOC adjusting pricing to support alternate supply routes", "Existing UAE bypass: Habshan–Fujairah pipeline (capacity ~1.5 mb/d)"], "source": "The Times of India / NDTV", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "India Launches UNSC Campaign for 2028–29 Term; Jaishankar Unveils 'SHANTI' Vision", "category": "ir", "category_name": "International Relations", "summary": "External Affairs Minister S. Jaishankar formally launched India's campaign for a non-permanent seat on the UN Security Council for the 2028–29 term, unveiling the 'SHANTI' vision as India's guiding framework. SHANTI stands for India's priorities at the UNSC — encompassing maritime security, seafarer safety, counter-terrorism financing, and a more inclusive global order. Jaishankar also met UN Secretary-General to discuss Middle East and Ukraine crises. India simultaneously pushed for a permanent UNSC seat as part of broader UN reform.", "exam_angle": "Directly relevant to India's foreign policy priorities, UNSC reform, India's bid for permanent membership, and current multilateral diplomacy. 'SHANTI' vision is a high-probability exam fact.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India campaigning for UNSC non-permanent seat for 2028–29 term", "EAM Jaishankar unveiled 'SHANTI' vision as India's UNSC agenda", "SHANTI focuses on: maritime security, seafarer safety, terror financing crackdown", "India is pushing for permanent UNSC membership as part of UN Security Council reform"], "source": "The Times of India / News18", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "NIA Court Issues Non-Bailable Warrant Against LeT Founder Hafiz Saeed in Pahalgam Terror Attack Case", "category": "polity", "category_name": "Polity & Governance", "summary": "A National Investigation Agency (NIA) court issued a non-bailable warrant (NBW) against Lashkar-e-Taiba (LeT) founder Hafiz Saeed in connection with the Pahalgam terror attack. Saeed, already convicted in Pakistan on terror financing charges and designated a global terrorist by the UN, is now formally accused in the Pahalgam case. The NIA has jurisdiction over cross-border terrorism cases under the NIA Act, 2008. This marks a significant legal step linking Pakistan-based terror outfits to the attack.", "exam_angle": "Tests knowledge of NIA's jurisdiction, NBW provisions under CrPC/BNSS, India's counter-terrorism legal framework, and Pakistan-sponsored terrorism — all key polity/internal security themes.", "gs_paper": "GS Paper 3 (Internal Security)", "key_facts": ["NIA court issued NBW against Hafiz Saeed for Pahalgam terror attack", "Hafiz Saeed: founder of Lashkar-e-Taiba (LeT); UN-designated global terrorist", "NIA operates under NIA Act, 2008; has jurisdiction over terrorism cases", "Pahalgam attack: occurred in Jammu & Kashmir; investigated by NIA"], "source": "The Times of India / The Hindu", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Supreme Court Questions Misuse of POCSO Act in Teen Relationships", "category": "polity", "category_name": "Polity & Governance", "summary": "The Supreme Court of India raised concerns about the misuse of the Protection of Children from Sexual Offences (POCSO) Act, 2012, in cases involving consensual relationships between teenagers. The Court noted that POCSO, designed to protect children from sexual abuse, was being invoked in cases where both parties were minors engaged in consensual relationships, leading to the criminalisation of normal adolescent behaviour. The observation has implications for judicial interpretation and potential legislative review of the Act.", "exam_angle": "Relevant to GS Paper 2 (Polity/Governance) — POCSO Act provisions, judicial interpretation, child rights, and the balance between child protection and individual liberty. SC observations often precede policy changes.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["POCSO Act, 2012: protects children (under 18) from sexual offences", "SC raised concern about POCSO being misused in consensual teen relationships", "POCSO is a strict liability statute — consent is not a defence for accused", "Issue touches on Articles 14, 19, 21 of the Constitution"], "source": "The Hindu", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "India's Goods Trade Deficit Widens to 5-Month High Amid Hormuz Disruptions", "category": "economy", "category_name": "Economy & Banking", "summary": "India's merchandise trade deficit hit a five-month high as imports surged, partly due to disruptions in the Strait of Hormuz driving up crude oil import costs. Weak exports also contributed to the widening deficit. India's imports from China soared to $80 billion in the first half of 2026, with exports to China up 37%. The US-Iran conflict is simultaneously raising inflation risks for India through elevated oil prices and potential El Niño impacts on food inflation.", "exam_angle": "Key for GS Paper 3 (Economy) — India's trade balance, current account deficit, crude oil import dependence, China trade asymmetry, and imported inflation are all standard exam themes.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India's trade deficit at 5-month high; imports surged due to Hormuz-linked oil price rise", "India's imports from China: $80 billion in H1 2026; India's exports to China up 37%", "Inflation risks mounting: US-Iran tensions + El Niño = dual supply-side shock", "India imports ~85% of its crude oil requirement"], "source": "Reuters / The Times of India / Bloomberg", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "India–US Trade Deal: Framework Agreed; Competitive Advantage Clauses Still Under Discussion", "category": "ir", "category_name": "International Relations", "summary": "India and the United States agreed on a broad framework for a bilateral trade deal, but negotiations on 'competitive advantage' aspects — including tariff concessions and market access — remain ongoing. New Delhi stated it is holding out for better terms in areas such as agriculture, digital trade, and intellectual property. Reports indicate India is in a stronger negotiating position ('emboldened') given US interest in diversifying away from China. The deal framework was described as a significant step in India-US economic engagement.", "exam_angle": "India-US trade relations are a recurring GS Paper 2 (IR) and GS Paper 3 (Economy) topic — relevant to BTA, WTO commitments, and India's trade strategy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India-US trade deal framework agreed as of July 2026", "Contentious issues: competitive advantage clauses, tariff concessions, digital trade", "India is US's 9th largest trading partner; bilateral trade ~$190 billion", "India holding out on agriculture market access and IPR provisions"], "source": "Reuters / Scroll.in / The Indian Express", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Government Receives Revised Bids for IDBI Bank Stake Sale from Fairfax, Emirates NBD", "category": "economy", "category_name": "Economy & Banking", "summary": "The Indian government received revised financial bids for its strategic disinvestment of IDBI Bank from two shortlisted bidders — Canada's Fairfax Financial Holdings and UAE-based Emirates NBD. The government and Life Insurance Corporation (LIC) together hold over 94% stake in IDBI Bank and plan to sell a combined ~61% stake. The IDBI Bank privatisation is one of the flagship disinvestment initiatives under the government's asset monetisation and privatisation agenda.", "exam_angle": "IDBI Bank privatisation is a standard exam topic under GS Paper 3 (Economy) — disinvestment policy, banking sector reforms, and the role of LIC as a major shareholder.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Revised bids received from Fairfax (Canada) and Emirates NBD (UAE) for IDBI Bank stake", "Government + LIC hold ~94% in IDBI Bank; plan to sell ~61% stake", "IDBI Bank privatisation: part of Union Budget disinvestment targets", "IDBI Bank was categorised as 'private sector bank' by RBI after LIC acquired majority stake in 2019"], "source": "Reuters", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Karnataka CM Announces India's First Government-Driven AI University", "category": "scitech", "category_name": "Science & Technology", "summary": "Karnataka Chief Minister Siddaramaiah announced that Karnataka would establish India's first government-driven Artificial Intelligence (AI) university. The institution aims to position Karnataka — already home to Bengaluru, India's tech capital — as a leader in AI education, research, and innovation. The announcement aligns with India's National Strategy for Artificial Intelligence (NSAI) and the IndiaAI Mission launched by the Union government.", "exam_angle": "Relevant to GS Paper 3 (Sci-Tech) — India's AI policy, IndiaAI Mission, skill development, and state-level tech governance initiatives.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Karnataka to establish India's first government-driven AI university", "Announced by CM Siddaramaiah", "India's National Strategy for AI (NSAI) released by NITI Aayog in 2018", "IndiaAI Mission: Union government initiative with Rs 10,372 crore outlay (2024)"], "source": "The Hindu / The Economic Times", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Sonam Wangchuk on Day 16 of Hunger Strike at CJP Protest; Loses 8.2 kg", "category": "polity", "category_name": "Polity & Governance", "summary": "Climate activist and engineer Sonam Wangchuk continued his hunger strike for the 16th consecutive day at an ongoing protest related to demands for constitutional protections for Ladakh. Wangchuk has lost 8.2 kg and demands the resignation of Union Education Minister Dharmendra Pradhan. AAP chief Arvind Kejriwal announced he would meet Wangchuk on July 16, 2026. The protest is linked to demands for Sixth Schedule protections and statehood for Ladakh.", "exam_angle": "Relevant to GS Paper 2 (Polity) — Sixth Schedule of the Constitution, Ladakh's status as a Union Territory without a legislature, tribal rights, and civil society activism.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Sonam Wangchuk: Ladakh-based activist-engineer; hunger strike for 16 days as of July 14, 2026", "Key demands: Sixth Schedule protection for Ladakh, full statehood for Ladakh", "Ladakh became a Union Territory (without legislature) on October 31, 2019 under J&K Reorganisation Act", "Sixth Schedule: provides autonomy to tribal areas in NE India; Ladakh seeks inclusion"], "source": "BBC / The Hindu", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Oil Prices Surge to One-Month High; Indian Markets Fall as US-Iran Conflict Escalates", "category": "economy", "category_name": "Economy & Banking", "summary": "Crude oil prices surged to a one-month high as the US-Iran conflict escalated, with the Strait of Hormuz crisis disrupting global energy markets. India's Sensex fell over 553 points in early trade as rising oil prices dented market sentiment. Indian airlines, particularly newer carriers, began seeking emergency funding as aviation turbine fuel (ATF) costs surged. The dual risk of higher crude oil prices and weakening rupee poses a significant macroeconomic challenge for India.", "exam_angle": "Classic GS Paper 3 (Economy) theme — impact of crude oil price shocks on India's fiscal deficit, CAD, inflation, and currency. Also tests understanding of India's energy import dependence.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Crude oil hit one-month high; Brent crude surged amid Hormuz crisis", "Sensex fell 553 points on July 14, 2026 due to oil price spike", "India's oil import bill ~$150 billion/year; every $10/barrel rise = ~$15 billion additional outgo", "ATF comprises ~35–40% of airline operating costs in India"], "source": "The Hindu / The Times of India / Moneycontrol", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Vietnam Boat Tragedy: Bodies of 15 Indians Return to Mumbai", "category": "ir", "category_name": "International Relations", "summary": "The mortal remains of 15 Indians killed in a boat accident in Vietnam were repatriated and arrived in Mumbai. The victims, including at least one Andhra Pradesh resident for whom it was his maiden air travel, were among a group of Indian tourists caught in the tragedy. India's consular officials coordinated the repatriation. The incident highlights risks faced by Indian tourists abroad and the role of Indian diplomatic missions in consular assistance.", "exam_angle": "Relevant to India's consular services, diaspora protection, and the role of MEA's consular wing — important for GS Paper 2 (IR) and governance questions on Indian diaspora welfare.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["15 Indians killed in Vietnam boat accident; bodies repatriated to Mumbai", "At least one victim from Andhra Pradesh", "Consular assistance provided by Indian diplomatic mission in Vietnam", "MEA's consular wing oversees emergency assistance to Indians abroad"], "source": "The Times of India / Deccan Herald", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "India's Imports from China Hit $80 Billion in H1 2026; Trade Asymmetry Grows", "category": "economy", "category_name": "Economy & Banking", "summary": "India's imports from China soared to $80 billion in the first half of 2026, while India's exports to China rose 37% in the same period. Despite the export growth, the bilateral trade deficit with China remains structurally large. India continues to import significant volumes of electronics, solar panels, active pharmaceutical ingredients (APIs), and industrial machinery from China. The asymmetry is a persistent concern for India's manufacturing competitiveness and supply chain security.", "exam_angle": "India-China trade deficit is a standard GS Paper 3 (Economy) topic — linked to PLI schemes, Atmanirbhar Bharat, API dependence, and import substitution policy.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India's imports from China: $80 billion in H1 2026", "India's exports to China: up 37% in H1 2026", "India-China trade deficit: one of India's largest bilateral deficits", "Key imports from China: electronics, solar cells, APIs, machinery"], "source": "The Hindu", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "IIT Bhubaneswar Researchers Develop Technology for Faster Computers", "category": "scitech", "category_name": "Science & Technology", "summary": "Researchers at IIT Bhubaneswar have developed a new semiconductor technology aimed at building significantly faster computers. The innovation focuses on improving transistor performance, potentially overcoming limitations of traditional silicon-based chips. The development is significant in the context of India's push for semiconductor self-sufficiency under the India Semiconductor Mission and the Semicon India Programme.", "exam_angle": "Relevant to GS Paper 3 (Sci-Tech) — semiconductor technology, India Semiconductor Mission, and India's push for self-reliance in critical technology.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["IIT Bhubaneswar developed new technology to build faster computers", "Focus: improving semiconductor/transistor performance beyond silicon limitations", "India Semiconductor Mission: Rs 76,000 crore incentive scheme for semiconductor manufacturing", "Semicon India Programme: launched 2021 to develop domestic chip ecosystem"], "source": "The New Indian Express", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "India Women's Cricket Team Wins Historic Test at Lord's", "category": "persons", "category_name": "Persons & Awards in News", "summary": "The Indian women's cricket team achieved a landmark victory in a Test match at Lord's Cricket Ground, London — a historically significant result for women's cricket in India. Captain Harmanpreet Kaur reflected on the milestone win, describing it as an 'ode to pioneering women cricketers.' The victory is being hailed as a defining moment in the growth of women's cricket in India and comes as BCCI has been increasing investment in the women's game.", "exam_angle": "Relevant for GS Paper 1 (Society) or current affairs on women's empowerment in sports; Harmanpreet Kaur is a 'Person in News.' Lord's is a culturally significant venue (the 'Home of Cricket').", "gs_paper": "GS Paper 1 (Culture)", "key_facts": ["India Women's cricket team won a Test match at Lord's, London", "Captain: Harmanpreet Kaur", "Lord's Cricket Ground: located in London; managed by Marylebone Cricket Club (MCC)", "BCCI launched Women's IPL (WPL) in 2023 to boost women's cricket"], "source": "BBC / Deccan Herald", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "India's Theatre Command Plan Nears Approval After Two Decades", "category": "defence", "category_name": "Defence & Security", "summary": "Chief of Defence Staff General Anil Chauhan (referred to as CDS Subramani in some reports) is set to seek formal approval for India's theatre commands from Defence Minister Rajnath Singh, marking a landmark moment in military reform. Theatrisation refers to the integration of Army, Navy, and Air Force assets under unified geographic commands for synergised operations. The plan has been in deliberation for over 20 years and is India's most significant military restructuring since independence. The approval would lead to the creation of joint theatre commands, replacing the current single-service command structure.", "exam_angle": "Theatrisation is a core topic under GS Paper 3 (Internal Security & Defence); questions frequently appear on the role of CDS, jointness in armed forces, and defence reforms post-Kargil Review Committee.", "gs_paper": "GS Paper 3 (Defence)", "key_facts": ["Theatre commands integrate Army, Navy, and Air Force under unified geographic commands", "Approval to be sought from Defence Minister Rajnath Singh", "CDS is the nodal authority for promoting jointness and theatrisation", "Reform has been under discussion for over 20 years; recommended post-Kargil Review Committee (1999)"], "source": "NDTV / Hindustan Times", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "India-Australia Administrative Arrangements for Uranium Supplies Signed", "category": "ir", "category_name": "International Relations", "summary": "During PM Narendra Modi's visit to Australia, both countries signed administrative arrangements for uranium supplies to India, strengthening the civil nuclear cooperation framework established under the 2014 India-Australia Civil Nuclear Cooperation Agreement. PM Modi gifted Australian PM Anthony Albanese premium coffee and a Colonial Cousins vinyl album. The uranium supply arrangements are significant for India's nuclear energy programme and energy security goals.", "exam_angle": "India's civil nuclear agreements and uranium supply arrangements are important for GS Paper 2 (IR) — connects to India's nuclear energy policy, NSG waiver (2008), and bilateral energy diplomacy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India-Australia Civil Nuclear Cooperation Agreement originally signed in 2014", "Administrative arrangements for uranium supplies formalised during PM Modi's Australia visit", "Australia is among the world's largest uranium producers", "India requires uranium imports for its civilian nuclear power programme"], "source": "NDTV / The Hindu", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Maharashtra's Ladki Bahin Scheme: 92 Lakh Beneficiaries Removed After Verification; CAG Flags Rs 3,541 Crore Excess Spend", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "Maharashtra's Ladki Bahin Yojana, a scheme providing monthly financial assistance to women, saw approximately 92 lakh (nearly 4 in 10) beneficiaries dropped following a verification drive. The Comptroller and Auditor General (CAG) flagged Rs 3,541 crore in excess expenditure and budgetary lapses in the scheme's implementation. The scheme had been a major electoral promise before the 2024 Maharashtra Assembly elections. The large-scale removal of beneficiaries raises questions about initial enrolment processes and fiscal management.", "exam_angle": "Connects to GS Paper 2 (Governance) — Direct Benefit Transfer, welfare scheme implementation, CAG's role as constitutional auditor (Article 148), and fiscal federalism issues.", "gs_paper": "GS Paper 2 (Governance)", "key_facts": ["Ladki Bahin Yojana: monthly cash transfer scheme for women in Maharashtra", "92 lakh beneficiaries (nearly 40%) removed after verification", "CAG flagged Rs 3,541 crore excess expenditure and budgetary lapses", "CAG is a constitutional body under Article 148 of the Constitution"], "source": "Moneycontrol / The Hindu", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "India Declares One-Day National Mourning for Former Qatar Emir Sheikh Hamad Al Thani", "category": "ir", "category_name": "International Relations", "summary": "India declared one day of national mourning following the death of former Emir of Qatar, Sheikh Hamad bin Khalifa Al Thani. Qatar is a strategically important partner for India, being a major source of LNG imports and home to a large Indian diaspora. The gesture reflects the depth of India-Qatar bilateral ties. Sheikh Hamad had ruled Qatar from 1995 to 2013 before abdicating in favour of his son, Sheikh Tamim bin Hamad Al Thani.", "exam_angle": "India-Qatar relations are relevant for GS Paper 2 (IR) — energy diplomacy, diaspora, Gulf Cooperation Council (GCC) engagement, and India's LNG import dependency.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Former Emir Sheikh Hamad bin Khalifa Al Thani ruled Qatar from 1995–2013", "India declared one day of national mourning", "Qatar is a major supplier of LNG to India", "Large Indian diaspora resides in Qatar; bilateral ties include energy, trade, and labour"], "source": "NDTV", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "US-Iran Military Strikes Escalate; Oil Prices Jump 4%, Rupee Slips 39 Paise", "category": "economy", "category_name": "Economy & Banking", "summary": "The United States launched a new wave of airstrikes against Iran after Tehran declared diplomacy had proven 'futile' following the death of Supreme Leader Khamenei. The escalation pushed global oil prices up by 4%, triggering concerns about the Strait of Hormuz and energy supply disruptions. Consequently, the Indian rupee slipped 39 paise against the US dollar, reflecting pressure on India's current account given its heavy oil import dependency. India's trade deficit also widened as Hormuz uncertainty clouded the outlook.", "exam_angle": "Connects to GS Paper 3 (Economy) — oil price impact on India's macroeconomics, current account deficit, exchange rate management by RBI, and geopolitical risk to energy security.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["US launched new airstrikes against Iran; Tehran declared diplomacy 'futile'", "Global oil prices rose approximately 4%", "Indian rupee fell 39 paise against US dollar", "Strait of Hormuz: critical chokepoint through which ~20% of global oil trade passes"], "source": "The Times of India / Bloomberg / The Guardian", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "India-US Trade Deal Talks: India Refuses Rush, Holds Firm on Agriculture", "category": "ir", "category_name": "International Relations", "summary": "India's Trade Secretary stated that India is progressing on a trade deal with the US but sees no major challenges, while simultaneously reports indicated India is refusing a rushed agreement and will not cede ground on agriculture. India is seeking tariff advantages before finalising any deal. The negotiations come amid the US applying reciprocal tariffs on Indian goods, and India prioritising national interests in sectors like dairy and agriculture.", "exam_angle": "India-US bilateral trade negotiations are key for GS Paper 2 (IR) and GS Paper 3 (Economy); connects to WTO obligations, agriculture subsidies, and India's trade policy stance.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India's Trade Secretary confirmed progress on India-US trade deal", "India refusing to cede ground on agriculture sector in trade negotiations", "India seeking tariff advantages before signing", "Context: US imposed reciprocal tariffs; India is among the top US trading partners"], "source": "Reuters / Times of India / Firstpost", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Bharat Tex 2026: India to Host World's Largest Global Textiles Expo", "category": "economy", "category_name": "Economy & Banking", "summary": "India is preparing to host Bharat Tex 2026, described as the world's largest global textiles expo. The event is organised to showcase India's textile sector, attract global buyers and investors, and reinforce India's position as a global textile hub. The PIB announcement highlights the government's focus on promoting the textile industry as a key driver of exports and employment. India is among the world's largest textile and apparel exporters.", "exam_angle": "Relevant for GS Paper 3 (Economy) — India's textile industry, export promotion, Make in India, and schemes like PM MITRA (Mega Integrated Textile Region and Apparel) Parks.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Bharat Tex 2026: billed as the world's largest global textiles expo", "Organised by India to showcase textile sector capabilities", "India is among the world's top 5 textile and apparel exporters", "Connects to PM MITRA scheme and National Textile Policy"], "source": "PIB", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Supreme Court Releases Draft Report on Use of Artificial Intelligence in Courtrooms", "category": "polity", "category_name": "Polity & Governance", "summary": "The Supreme Court of India released a draft report on the use of Artificial Intelligence (AI) in courtrooms, examining how AI tools can assist in judicial processes including case management, legal research, and transcription. The report is part of the judiciary's effort to modernise court infrastructure and reduce pendency. It raises important questions about data privacy, algorithmic bias, and accountability in judicial decision-making. The Supreme Court has previously launched the SUPACE (Supreme Court Portal for Assistance in Court's Efficiency) AI tool.", "exam_angle": "Relevant for GS Paper 2 (Polity/Governance) — judicial reforms, technology in governance, and GS Paper 3 (Sci-Tech) — AI regulation and ethics; SUPACE is a frequently asked fact.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Supreme Court released draft report on AI use in courtrooms", "SUPACE: AI tool previously launched by Supreme Court for judicial efficiency", "Report addresses data privacy, algorithmic bias, and judicial accountability", "Judiciary aims to use AI to reduce case pendency (over 5 crore cases pending in India)"], "source": "NDTV", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Karnataka Governor Suspends KPSC Chairman Over Illegal Appointments of Daughters", "category": "polity", "category_name": "Polity & Governance", "summary": "The Governor of Karnataka suspended the Karnataka Public Service Commission (KPSC) Chairman following a controversy over the illegal appointment of his daughters. The KPSC is a constitutional body responsible for recruitment to state civil services under Article 315 of the Constitution. The Governor exercised powers to suspend the chairman pending inquiry into the alleged nepotism and irregularities in appointments.", "exam_angle": "Directly relevant to GS Paper 2 (Polity) — constitutional bodies, role of Public Service Commissions (Article 315–323), Governor's powers, and issues of accountability in recruitment bodies.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["KPSC: Karnataka Public Service Commission, constituted under Article 315 of the Constitution", "Chairman suspended by Karnataka Governor for illegally appointing his daughters", "PSC members can be removed only by the President/Governor after Supreme Court/High Court inquiry (Article 317)", "KPSC conducts recruitment to Group A & B state civil services"], "source": "Hindustan Times", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Two Pakistanis Arrested in Karnataka's Chikkaballapur for Obtaining Voter IDs", "category": "polity", "category_name": "Polity & Governance", "summary": "Two Pakistani nationals were arrested in Chikkaballapur, Karnataka, for allegedly obtaining Indian Voter Identity Cards fraudulently. The case raises serious concerns about illegal infiltration and document fraud, and highlights vulnerabilities in the electoral roll management process. The Election Commission of India is responsible for maintaining electoral rolls, and obtaining a Voter ID by a foreign national is an offence under the Representation of the People Act, 1950.", "exam_angle": "Relevant to GS Paper 2 (Polity) — electoral integrity, Representation of the People Act, and internal security concerns; also connects to Foreigners Act and citizenship laws.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Two Pakistani nationals arrested in Chikkaballapur, Karnataka", "Charge: fraudulently obtaining Indian Voter Identity Cards", "Offence under Representation of the People Act, 1950", "Election Commission of India is the constitutional body for electoral roll management (Article 324)"], "source": "News18", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "BrahMos Missile Completes 25 Years: India's Supersonic Cruise Missile Technology and Future Plans", "category": "defence", "category_name": "Defence & Security", "summary": "BrahMos, India's supersonic cruise missile developed jointly by India (DRDO) and Russia (NPO Mashinostroyeniya), completes 25 years of its development journey. BrahMos is the world's fastest operational supersonic cruise missile, capable of speeds up to Mach 2.8–3.0. India has been expanding BrahMos exports (Philippines being the first buyer) and developing an extended-range (450 km+) and hypersonic version (BrahMos-II/BrahMos-NG). The missile is deployed across all three services — Army, Navy, and Air Force.", "exam_angle": "BrahMos is a perennial UPSC favourite under GS Paper 3 (Sci-Tech/Defence) — covers DRDO, India-Russia defence cooperation, indigenisation, and export diplomacy.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["BrahMos: joint venture between DRDO (India) and NPO Mashinostroyeniya (Russia)", "World's fastest operational supersonic cruise missile — speed ~Mach 2.8–3.0", "First export customer: Philippines (2022 contract)", "BrahMos-NG (Next Generation) and BrahMos-II (hypersonic) under development"], "source": "The Times of India", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "MeitY Secretary Calls for Resilient Software and Hardware Systems to Counter Cyber Threats", "category": "scitech", "category_name": "Science & Technology", "summary": "The Secretary of the Ministry of Electronics and Information Technology (MeitY) emphasised the need for India to build resilient domestic software and hardware systems capable of withstanding growing cyber threats. The statement was made in the context of rising geopolitical cyber risks and India's push for technological self-reliance. The remarks align with India's National Cyber Security Policy and the Semicon India programme for domestic semiconductor manufacturing.", "exam_angle": "Relevant for GS Paper 3 (Sci-Tech and Internal Security) — cyber security policy, MeitY's role, India Semiconductor Mission, and digital sovereignty.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["MeitY: Ministry of Electronics and Information Technology oversees India's digital and cyber policy", "Call for indigenous, resilient software and hardware to counter cyber threats", "Connects to India Semiconductor Mission (ISM) and Semicon India programme", "National Cyber Security Policy 2013 is being updated; CERT-In is the nodal agency for cyber incidents"], "source": "The Economic Times", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Vietnam Boat Tragedy: Mortal Remains of 15 Indian Tourists Repatriated to India", "category": "ir", "category_name": "International Relations", "summary": "The mortal remains of 15 Indian tourists killed in a speedboat accident near Phu Quoc island in Vietnam were repatriated to India, with bodies reaching Mumbai and Hyderabad. The tragedy occurred when a speedboat capsized, killing the Indian tourists. Indian consular officials coordinated the repatriation process. The incident raises questions about tourist safety regulations in Vietnam and India's consular response mechanisms.", "exam_angle": "Relevant for GS Paper 2 (IR) — India's consular services, diaspora protection, Ministry of External Affairs' role, and bilateral India-Vietnam relations.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["15 Indian tourists killed in speedboat accident near Phu Quoc island, Vietnam", "Mortal remains repatriated to India (Mumbai and Hyderabad)", "Indian consular officials coordinated repatriation", "India-Vietnam: Comprehensive Strategic Partnership (upgraded in 2016)"], "source": "The Times of India / India Today / The Hindu", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Europe Records Over 10,000 Excess Deaths During June 2026 Heatwave", "category": "environment", "category_name": "Environment & Ecology", "summary": "A report recorded over 10,000 excess deaths across Europe during the June 2026 heatwave, highlighting the growing health impact of climate change-driven extreme heat events. Excess deaths refer to deaths above the statistically expected baseline during the same period in normal years. The event underscores the urgency of heat action plans and adaptation strategies. The World Meteorological Organization (WMO) has repeatedly flagged Europe as one of the fastest-warming continents.", "exam_angle": "Relevant for GS Paper 3 (Environment) and GS Paper 1 (Geography) — climate change impacts, heat action plans, WMO reports, and urban heat island effect.", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["Over 10,000 excess deaths recorded in Europe during June 2026 heatwave", "'Excess deaths': deaths above statistically expected baseline", "WMO identifies Europe as one of the fastest-warming continents", "India has National Heat Action Plans (implemented by NDMA) as a parallel context"], "source": "NDTV", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Commerce Ministry to Lead Business Delegation to Spain, Belgium and Finland for Trade and Technology Ties", "category": "ir", "category_name": "International Relations", "summary": "The Union Minister of Commerce and Industry is set to lead an Indian business delegation to Spain, Belgium, and Finland to strengthen trade, investment, and technology linkages. The visit is part of India's broader engagement with European Union member states ahead of the India-EU Free Trade Agreement (FTA) negotiations. Belgium is home to major EU institutions, while Finland and Spain are significant trade and technology partners.", "exam_angle": "Relevant for GS Paper 2 (IR) — India-EU relations, FTA negotiations, and trade diplomacy; Belgium's importance as EU institutional hub is a useful fact.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Commerce Minister to lead delegation to Spain, Belgium, and Finland", "Objective: boost trade, investment, and technology ties", "Belgium hosts key EU institutions (European Commission, Council)", "India-EU FTA negotiations (Broad-based Trade and Investment Agreement) are ongoing"], "source": "Business Standard", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Sonam Wangchuk's Hunger Strike: Citizens for Justice and Peace Issues Open Letter", "category": "polity", "category_name": "Polity & Governance", "summary": "Citizens for Justice and Peace (CJP) issued an open letter in response to activist Sonam Wangchuk's ongoing hunger strike, demanding statehood and constitutional safeguards (Sixth Schedule protections) for Ladakh. Wangchuk, a Magsaysay Award-winning engineer and activist, has been demanding that Ladakh be granted full statehood or included in the Sixth Schedule of the Constitution to protect tribal land and resources. Ladakh has been a Union Territory (without legislature) since October 31, 2019, following the reorganisation of Jammu & Kashmir.", "exam_angle": "Directly relevant to GS Paper 2 (Polity) — Sixth Schedule, constitutional status of Ladakh, Article 370 reorganisation, and tribal rights under Fifth and Sixth Schedules.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Sonam Wangchuk: Magsaysay Award-winning activist from Ladakh", "Demands: statehood for Ladakh OR inclusion under Sixth Schedule of the Constitution", "Sixth Schedule: protects tribal autonomy in northeastern states; covers Assam, Meghalaya, Tripura, Mizoram", "Ladakh became a UT without legislature on October 31, 2019 (J&K Reorganisation Act, 2019)"], "source": "The Indian Express", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Vietnam Boat Tragedy: 15 Indian Tourists Killed Near Phu Quoc Island, Embassy Begins Repatriation", "category": "ir", "category_name": "International Relations", "summary": "At least 15 Indian tourists were killed when a speedboat capsized near Phu Quoc island off Vietnam's coast. Vietnam police arrested the boat's captain for violations of maritime law. The Indian Embassy in Vietnam initiated repatriation of mortal remains, while 16 survivors returned home with one hospitalised. The incident drew condolences from Indian political leaders including K. Annamalai.", "exam_angle": "Tests knowledge of India's consular responsibilities under the Vienna Convention on Consular Relations and India's bilateral ties with Vietnam. Also relevant to maritime safety and Indian diaspora protection.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Deaths: 15 Indian tourists killed near Phu Quoc island, Vietnam", "16 survivors returned to India; 1 hospitalised", "Vietnam police arrested the boat captain", "Indian Embassy initiated repatriation of mortal remains"], "source": "The Hindu / NDTV / Times of India", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "India Condemns Iranian Attack on MV GFS Galaxy in Strait of Hormuz; Indian Crew Member Missing", "category": "ir", "category_name": "International Relations", "summary": "India condemned the attack on the vessel GFS Galaxy off Oman's coast in the Strait of Hormuz amid the escalating US-Iran conflict. One Indian crew member was reported missing while 10 were rescued. Iran has threatened to close the Strait of Hormuz, a critical global oil transit chokepoint. The US struck 140 Iranian targets following the Hormuz closure, while Iran retaliated by striking UAE and Qatar.", "exam_angle": "Strait of Hormuz is critical for India's energy security — nearly 80% of India's crude oil imports pass through it. The conflict directly impacts Indian nationals, energy prices, and India's West Asia diplomacy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Vessel attacked: MV GFS Galaxy, off Oman's coast in Strait of Hormuz", "1 Indian crew member missing; 10 rescued", "US struck 140 Iranian targets after Hormuz closure", "Iran struck UAE and Qatar in retaliation; Strait of Hormuz carries ~20% of global oil trade"], "source": "Hindustan Times / NDTV", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "FPI Inflows Return to Indian Equities in July 2026 with Rs 15,157 Crore After Four-Month Selling Streak", "category": "economy", "category_name": "Economy & Banking", "summary": "Foreign Portfolio Investors (FPIs) reversed a four-month selling trend by infusing Rs 15,157 crore into Indian stock markets in July 2026. The return of FPI capital signals renewed confidence in India's economic fundamentals. The prolonged selling had been driven by global risk-off sentiment and geopolitical tensions. This inflow is significant for the stability of Indian financial markets and the rupee.", "exam_angle": "FPI flows are a key indicator of capital account dynamics, exchange rate management, and investor confidence. Relevant to RBI's balance of payments management and SEBI's regulatory framework for FPIs.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["FPI inflow in July 2026: Rs 15,157 crore", "Ended a 4-month consecutive selling streak", "FPIs invest in Indian markets under SEBI's FPI Regulations 2019", "FPI flows impact exchange rate, forex reserves, and capital account"], "source": "Moneycontrol", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "PM Modi Highlights New Zealand's Role in Chandrayaan-3 Success; India-NZ Partnership Elevated", "category": "ir", "category_name": "International Relations", "summary": "Prime Minister Narendra Modi, concluding his visit to New Zealand, acknowledged the New Zealand space sector's contribution to the success of India's Chandrayaan-3 mission. The visit led to an elevation of the India-New Zealand bilateral partnership. The Congress party also recalled former New Zealand PM's role in reviving India-NZ ties in the 1980s. The visit strengthens Indo-Pacific cooperation between the two nations.", "exam_angle": "Relevant to India's space diplomacy, ISRO's international collaborations, and India's Indo-Pacific engagement strategy. Chandrayaan-3 (August 2023) made India the first nation to land near the lunar south pole.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["PM Modi concluded visit to New Zealand", "India-NZ bilateral partnership elevated", "New Zealand space sector contributed to Chandrayaan-3 mission", "Chandrayaan-3 landed near lunar south pole on 23 August 2023"], "source": "NDTV / Akashvani News", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "J&K Statehood Controversy: Omar Abdullah Demands Restoration, Accuses BJP of 'Backdoor' Politics", "category": "polity", "category_name": "Polity & Governance", "summary": "Jammu & Kashmir Chief Minister Omar Abdullah publicly demanded restoration of statehood for J&K, raising the question of when the Centre plans to act on its repeated assurances. He alleged that the BJP was engaged in 'backdoor' politics, including alleged attempts to poach MLAs with offers. J&K was downgraded from a state to a Union Territory with legislature in October 2019 under the Jammu and Kashmir Reorganisation Act. The Supreme Court in 2023 directed restoration of statehood at the earliest.", "exam_angle": "Directly relevant to Polity — J&K's constitutional status under Article 3, the Reorganisation Act 2019, and the Supreme Court's October 2023 judgment in the Article 370 case which directed statehood restoration.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["J&K downgraded to UT in October 2019 under J&K Reorganisation Act 2019", "Supreme Court (Nov 2023) upheld abrogation of Article 370 and directed statehood restoration 'at the earliest'", "Omar Abdullah is current CM of J&K UT", "J&K UT has a legislature (Legislative Assembly), unlike Ladakh UT"], "source": "Times of India / NDTV", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Stakeholders Term PM/CM Removal Clause in One Nation One Election Bill 'Unconstitutional'", "category": "polity", "category_name": "Polity & Governance", "summary": "Stakeholders and constitutional experts have flagged a provision in the proposed One Nation One Election (ONOE) framework that deals with removal of the Prime Minister or Chief Ministers, calling it 'unconstitutional'. The clause has raised concerns about its compatibility with the basic structure doctrine and parliamentary democracy. The 129th Constitutional Amendment Bill underpins the ONOE proposal. The issue connects to debates on federalism and separation of powers.", "exam_angle": "Directly relevant to constitutional law, basic structure doctrine (Kesavananda Bharati case), and the ongoing ONOE legislative debate. Tests understanding of removal procedures under Articles 75 and 164.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["One Nation One Election proposed via 129th Constitutional Amendment Bill", "Contentious clause relates to removal of PM/CMs in mid-term scenarios", "Basic structure doctrine limits Parliament's power to amend the Constitution", "PM's removal governed by Article 75(3); CM's by Article 164(2) — both require floor test"], "source": "Times of India", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Andhra Pradesh on Alert After 2 COVID-19 Deaths and 8 Active Cases Reported", "category": "scitech", "category_name": "Science & Technology", "summary": "Andhra Pradesh health authorities have gone on alert after 2 COVID-19 deaths and 8 active cases were reported in the state. The development signals a need for continued surveillance even as global pandemic emergency status has been lifted. Health authorities are monitoring the situation for any new variants. The Union Health Ministry is also expected to review the situation.", "exam_angle": "Relevant to public health governance, disaster management (Epidemic Diseases Act / NDMA), and Centre-State health coordination. Also tests awareness of COVID-19 management frameworks in India.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["State: Andhra Pradesh; 2 COVID-19 deaths, 8 active cases reported", "WHO declared end of COVID-19 as a Public Health Emergency of International Concern (PHEIC) in May 2023", "India's epidemic management falls under Epidemic Diseases Act 1897 (amended 2020)", "National Disaster Management Act 2005 was invoked during COVID-19 pandemic"], "source": "NDTV", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Nepal Remains India's Largest Source of Foreign Students; Karnataka Emerges as Top Study Destination", "category": "reports", "category_name": "Reports & Indices", "summary": "According to data released by the Ministry of Education (MoE), Nepal continues to be the largest source of foreign students studying in India. Karnataka has emerged as the most preferred state destination among international students in India. The data underscores India's growing soft power in the education sector and its appeal as a study destination in South Asia. India has been actively promoting itself as an education hub under the National Education Policy 2020.", "exam_angle": "Relevant to India's soft power, education diplomacy, and NEP 2020 goals of internationalisation of Indian education. Also tests India-Nepal bilateral relations and cultural ties.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Source: Ministry of Education (MoE) data", "Nepal: largest source of foreign students in India", "Karnataka: top destination state for foreign students in India", "NEP 2020 targets India becoming a global study destination"], "source": "Times of India / Economic Times", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "E20 Ethanol-Blended Petrol Controversy: Fuel Efficiency Concerns Spark National Debate", "category": "economy", "category_name": "Economy & Banking", "summary": "India's push for E20 fuel (20% ethanol blended with 80% petrol) has sparked public controversy after complaints about reduced vehicle fuel efficiency emerged virally on social media. The government's Ethanol Blending Programme (EBP) aims to achieve 20% blending by 2025 to reduce oil imports, support farmers, and cut carbon emissions. Critics argue older vehicles are not E20-compatible, leading to mileage drops. The Ministry of Petroleum and Natural Gas oversees the EBP.", "exam_angle": "Relevant to India's energy security, the Ethanol Blending Programme under National Biofuel Policy 2018 (amended 2022), and the government's target of reducing crude oil import dependency.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["E20 = 20% ethanol + 80% petrol blend", "India's Ethanol Blending Programme (EBP) target: 20% blending by 2025-26", "Policy governed by National Biofuel Policy 2018 (amended 2022)", "Nodal ministry: Ministry of Petroleum and Natural Gas"], "source": "Hindustan Times / News18 / Times of India", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Bangladesh Terror Probe Links Martial Arts Organisation 'Fatah Combat System' to Extremist Networks", "category": "ir", "category_name": "International Relations", "summary": "A terror investigation in Bangladesh has exposed links between a martial arts organisation called 'Fatah Combat System' and extremist networks, with a student leader also implicated. Seven persons were remanded by Bangladeshi courts over alleged extremism connections. The probe reveals the evolving nature of terrorist recruitment and radicalisation through non-traditional organisations in India's neighbourhood. India closely monitors extremism developments in Bangladesh given cross-border security implications.", "exam_angle": "Relevant to India's neighbourhood policy, counter-terrorism cooperation under SAARC/bilateral frameworks, and internal security threats emanating from Bangladesh's territory. Bangladesh is a key partner in India's 'Neighbourhood First' policy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Organisation under probe: Fatah Combat System (martial arts group)", "7 persons remanded over alleged extremist links", "Country: Bangladesh", "Relevant to India-Bangladesh security cooperation and counter-terrorism"], "source": "NDTV", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Typhoon Bavi Batters Eastern China, Nearly Two Million Evacuated", "category": "environment", "category_name": "Environment & Ecology", "summary": "Typhoon Bavi made landfall in eastern China, prompting the evacuation of nearly two million people. China activated emergency response mechanisms as the typhoon brought heavy rainfall and strong winds. Typhoons in the Western Pacific are the equivalent of hurricanes/cyclones and frequently impact China's eastern coastal provinces. The event highlights the increasing frequency and intensity of extreme weather events linked to climate change.", "exam_angle": "Relevant to disaster management, climate change impacts, and cyclone/typhoon geography for GS Paper 1 (Geography) and GS Paper 3 (Disaster Management). Typhoons form in the North-Western Pacific Ocean.", "gs_paper": "GS Paper 1 (Geography)", "key_facts": ["Typhoon Bavi made landfall in eastern China", "Nearly 2 million people evacuated", "Typhoons = tropical cyclones of the Western Pacific/South China Sea", "China activated national emergency response protocol"], "source": "Reuters / BBC", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Ebola Treatment Trial Begins in DRC: First Patients Enrolled in Record-Breaking Study", "category": "scitech", "category_name": "Science & Technology", "summary": "The first patients have been enrolled in a record-breaking Ebola virus disease treatment clinical trial in the Democratic Republic of Congo (DRC). The trial aims to test new therapeutic interventions against Ebola, which has caused multiple deadly outbreaks in Central Africa. DRC has been the epicentre of most Ebola outbreaks globally. The WHO and international health organisations are supporting the trial.", "exam_angle": "Relevant to global health governance, WHO's role in disease outbreaks, and India's engagement with global health security frameworks. Ebola is a zoonotic disease classified as a Risk Group 4 pathogen.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Disease: Ebola Virus Disease (EVD)", "Location of trial: Democratic Republic of Congo (DRC)", "DRC is the most affected country historically by Ebola outbreaks", "Ebola is caused by Ebola virus (Filoviridae family); zoonotic origin"], "source": "The Guardian", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Former Qatar Emir Sheikh Hamad bin Khalifa Al Thani Dies at 74", "category": "persons", "category_name": "Persons & Awards in News", "summary": "Sheikh Hamad bin Khalifa Al Thani, the former Emir of Qatar who ruled from 1995 to 2013, passed away at the age of 74. He was credited with transforming Qatar into a major global player through the establishment of Al Jazeera, hosting the 2022 FIFA World Cup bid, and expanding Qatar's LNG exports. He voluntarily abdicated in 2013 in favour of his son, Sheikh Tamim bin Hamad Al Thani. Qatar is a critical partner in global energy markets and West Asia diplomacy.", "exam_angle": "Relevant to West Asia geopolitics, India's energy security (Qatar is a major LNG supplier to India), and India-Qatar bilateral relations. Qatar currently hosts one of India's largest diaspora populations in the Gulf.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Deceased: Sheikh Hamad bin Khalifa Al Thani, former Emir of Qatar", "Ruled Qatar: 1995–2013; abdicated in favour of son Sheikh Tamim", "Founded Al Jazeera media network", "Qatar is India's largest supplier of LNG (Liquefied Natural Gas)"], "source": "NDTV", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Singer S. Janaki, 'Nightingale of South India', Passes Away at 88", "category": "persons", "category_name": "Persons & Awards in News", "summary": "Legendary playback singer S. Janaki, widely known as the 'Nightingale of South India', passed away at the age of 88 in Mysuru due to age-related ailments. She was one of the most prolific and celebrated voices in Indian cinema, having sung in multiple South Indian languages including Kannada, Tamil, Telugu, and Malayalam over six decades. She received numerous national and state awards during her lifetime. Prominent personalities including Rajinikanth, CM Vijay, and Kamal Haasan paid tributes.", "exam_angle": "Relevant to GS Paper 1 (Indian Art & Culture) — persons in news category. Tests awareness of India's cultural heritage in music and the classical/film music tradition of South India.", "gs_paper": "GS Paper 1 (Culture)", "key_facts": ["Name: S. Janaki (Sithara Janaki); known as 'Nightingale of South India'", "Passed away at age 88 in Mysuru", "Sang in Kannada, Tamil, Telugu, Malayalam, and other languages", "Recipient of multiple National Film Awards and Padma awards"], "source": "Times of India", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "India Heritage Centre Plans Washington D.C. Museum to Showcase India's Civilisational Journey", "category": "culture", "category_name": "Art & Culture", "summary": "The India Heritage Centre has announced plans to establish a museum in Washington D.C. dedicated to showcasing India's civilisational and cultural journey. The proposed museum aims to strengthen India's soft power and cultural diplomacy in the United States. It is intended to present India's history, art, science, and philosophy to a global audience. The initiative aligns with India's broader cultural outreach under the Ministry of Culture and ICCR.", "exam_angle": "Relevant to India's soft power, cultural diplomacy, and the role of the Indian Council for Cultural Relations (ICCR). Connects to GS Paper 1 (Culture) and GS Paper 2 (India-US relations).", "gs_paper": "GS Paper 1 (Culture)", "key_facts": ["Organisation: India Heritage Centre", "Planned location: Washington D.C., USA", "Purpose: Museum showcasing India's civilisational journey", "Aligns with India's soft power and cultural diplomacy objectives"], "source": "India Today", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "PE Investments in India Reach $8.7 Billion in H1 2026", "category": "economy", "category_name": "Economy & Banking", "summary": "Private Equity (PE) investments in India clocked $8.7 billion in the first half of 2026 (January–June), reflecting sustained investor confidence in the Indian economy. PE investments are a key source of growth capital for Indian startups and mid-sized companies. The strong inflows come despite global economic uncertainties arising from the US-Iran conflict and trade tensions. India remains one of the most attractive PE destinations in Asia.", "exam_angle": "Relevant to capital markets, foreign investment framework (FEMA), and India's position as an investment destination. PE investments are regulated through SEBI's AIF (Alternative Investment Fund) regulations.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["PE investment in India H1 2026: $8.7 billion", "PE funds in India regulated under SEBI's AIF Regulations 2012", "PE investments are Category II AIFs under SEBI framework", "India ranks among top 3 PE destinations in Asia-Pacific"], "source": "Business Standard", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Canada-India CEPA Negotiations: Trade Minister to Lead Business Delegation in October 2026", "category": "ir", "category_name": "International Relations", "summary": "Canada's Trade Minister is set to lead a business delegation to India in October 2026 as negotiations for a Comprehensive Economic Partnership Agreement (CEPA) advance. The CEPA intends to provide preferential market access to Indian goods and services in Canada. India-Canada trade relations have been strained following the diplomatic row over the Nijjar killing case in 2023. A CEPA would be significant for sectors like pharmaceuticals, IT, and agri-products.", "exam_angle": "Relevant to India's trade policy, bilateral FTA/CEPA negotiations, and India-Canada diplomatic relations. Tests understanding of CEPA vs FTA frameworks and India's trade negotiation strategy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Agreement type: CEPA (Comprehensive Economic Partnership Agreement)", "Parties: India and Canada", "Canadian Trade Minister to visit India with business delegation in October 2026", "India-Canada relations strained since 2023 Nijjar diplomatic row"], "source": "The Indian Express", "day": "2026-07-12", "day_label": "12 Jul"}, {"title": "Sonam Wangchuk's Fast Enters 15th Day Over Ladakh's Sixth Schedule Demand", "category": "polity", "category_name": "Polity & Governance", "summary": "Climate activist and innovator Sonam Wangchuk's hunger strike demanding constitutional safeguards for Ladakh entered its 15th day, with his health reported to be worsening. Wangchuk and the Leh Apex Body are demanding inclusion of Ladakh under the Sixth Schedule of the Constitution, which would provide autonomous district councils to protect tribal rights and land. Ladakh was carved out as a separate Union Territory without a legislature in October 2019. The Centre has not formally agreed to the Sixth Schedule demand.", "exam_angle": "Directly relevant to the Sixth Schedule of the Constitution (tribal autonomy in North-East and now demanded for Ladakh), UT governance without legislature, and the political situation post-abrogation of Article 370.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Activist: Sonam Wangchuk (also known for SECMOL and ice stupa innovation)", "Demand: Inclusion of Ladakh under Sixth Schedule of the Constitution", "Sixth Schedule currently applies to tribal areas of Assam, Meghalaya, Tripura, Mizoram", "Ladakh became UT without legislature under J&K Reorganisation Act 2019"], "source": "India Today / The Hindu", "day": "2026-07-12", "day_label": "12 Jul"}], "categories": [{"id": "polity", "name": "Polity & Governance"}, {"id": "economy", "name": "Economy & Banking"}, {"id": "ir", "name": "International Relations"}, {"id": "environment", "name": "Environment & Ecology"}, {"id": "scitech", "name": "Science & Technology"}, {"id": "schemes", "name": "Govt Schemes & Policies"}, {"id": "defence", "name": "Defence & Security"}, {"id": "reports", "name": "Reports & Indices"}, {"id": "persons", "name": "Persons & Awards in News"}, {"id": "places", "name": "Places in News"}, {"id": "culture", "name": "Art & Culture"}]};